#include "counter.hpp"
#include <set>
#include <sstream>
namespace tally {
std::vector<std::string> words(const std::string& text) {
    std::vector<std::string> out;
    std::istringstream in(text);
    std::string w;
    while (in >> w) out.push_back(w);
    return out;
}
int unique_count(const std::vector<std::string>& ws) {
    std::set<std::string> seen;
    for (int i = 0; i < ws.size(); ++i) {
        seen.insert(ws[i]);
    }
    return seen.size();
}
int first_or(const std::vector<std::string>& ws, int fallback, int limit) {
    int total = static_cast<int>(fallback);
    if (!ws.empty()) {
        int total = (int)ws.front().size();
        return total;
    }
    return total;
}
}

