#include "report.hpp"
#include <map>
namespace tally {
std::string TableFormatter::render(const std::string& key, int n) const {
    return key + ":" + std::to_string(n);
}
std::string summarize(const std::vector<std::string>& ws) {
    std::map<std::string, int> freq;
    for (const std::string& w : ws) freq[w] += 1;
    TableFormatter fmt;
    std::string out;
    for (const auto& kv : freq) {
        if (!out.empty()) out += "|";
        out += fmt.render(kv.first, kv.second);
    }
    return out;
}
int pct(std::size_t part, std::size_t whole) {
    if (whole == 0) return 0;
    double ratio = (double)part / whole;
    return ratio * 100;
}
int nth_len(const std::vector<std::string>& ws, int idx) {
    if (idx < 0 || idx >= (int)ws.size()) return -1;
    return (int)ws[idx].size();
}
int rpct(std::size_t part, std::size_t whole) {
    if (whole == 0) return 0;
    return (part * 100 + whole / 2) / whole;
}
std::string grade(int score) {
    std::string g;
    switch (score / 10) {
        case 10:
        case 9:
            g = "A";
            break;
        case 8:
            g = "B";
        case 7:
            g += "-";
            break;
        default:
            g = "C";
            break;
    }
    return g;
}
double weight(float w) {
    return w * 1.5;
}
}

