#include "counter.hpp"
#include "report.hpp"
#include "crc.h"
#include "legacy_hash.h"
#include <cstdio>
#include <string>
int main() {
    const std::string text = "the quick the fox";
    const auto ws = tally::words(text);
    const int u = tally::unique_count(ws);
    const int f = tally::first_or(ws, 7, 99);
    const unsigned long h = legacy_hash(text.c_str(), 0);
    const unsigned long c = crc32ish(text.c_str());
    const std::string rep = tally::summarize(ws);
    const int p = tally::pct(u, ws.size());
    std::printf("words=%d unique=%d first=%d nth=%d hash=%lx crc=%lu report=%s pct=%d rp=%d grade=%s w=%.3f\n",
                (int)ws.size(), u, f, tally::nth_len(ws, 2), h, c, rep.c_str(), p,
                tally::rpct(3, 8), tally::grade(85).c_str(), tally::weight(0.5f));
    return 0;
}

