#include "crc.h"
#include <string.h>

unsigned long crc32ish(const char *s)
{
    unsigned long h = 0UL;
    size_t n = strlen(s);
    size_t i;
    for (i = 0; i < n; ++i) {
        h = h * 31UL + (unsigned long)(unsigned char)s[i];
    }
    return h;
}

