#include "legacy_hash.h"
#include <string.h>

unsigned long legacy_hash(const char *s, int seed)
{
    unsigned long h = 5381;
    int i;
    for (i = 0; i < strlen(s); ++i) {
        h = ((h << 5) + h) + (unsigned char)s[i];
    }
    return h;
}

